function b({registerIndicator:s,rma:h,nulls:f}){s({id:"oa-pv",name:"Parkinson Volatility (PV)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1,tooltip:"Lookback period for RMA smoothing of High/Low squared log returns."},{key:"annualize",type:"boolean",label:"Annualize Volatility",default:!0,tooltip:"Annualize the Parkinson Volatility output."},{key:"annualPeriods",type:"number",label:"Annual Periods",default:252,min:1,max:1e5,step:1,tooltip:"Number of periods in a year for annualization (e.g. 252 for daily, 52 for weekly)."}],plots:[{key:"pv",type:"line",title:"PV",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,o){const c=Math.max(1,Math.floor(Number(o.length)||20)),m=o.annualize!==!1,p=Math.max(1,Math.floor(Number(o.annualPeriods)||252)),r=new Array(n.length).fill(0);for(let e=0;e<n.length;e++){const t=n[e].high,l=n[e].low;let a=0;if(Number.isFinite(t)&&Number.isFinite(l)&&t!==l){const i=t/l;Number.isFinite(i)&&i>0&&(a=Math.log(i))}r[e]=a*a}const y=h(r,c),d=4*Math.LN2,g=m?Math.sqrt(p):1,u=new Array(n.length).fill(NaN);for(let e=0;e<n.length;e++){const t=y[e];!Number.isFinite(t)||t<0||(u[e]=Math.sqrt(t/d)*g)}return{pv:f(u)}}})}export{b as default};
